static void abortAndFinishActiveAnimation() {
  if (animating) {
    animating = false;
    nextChime = 0xFFFFFFFF;
    renderPageFinal(pages[curPage], curAccent);
    drawHeader(quotes[curQuote], false);
    delay(20);
