1	# ESP32 ↔ Turso Cloud (Read-Only) Integration & Minimal Rendering Guide
2	
3	This guide details how your **ESP32 microcontroller** securely accesses your **Turso Cloud SQLite database** in **read-only mode** 24/7 over Wi-Fi, and outlines the **minimal 5-point metadata specification** for hardware quote rendering.
4	
5	---
6	
7	## 1. Security Architecture: Dedicated Read-Only Token
8	
9	To protect your cloud database from tampering or hardware theft, the ESP32 should **never hold a full read-write token**. Turso allows creating tokens restricted exclusively to `SELECT` operations.
10	
11	### Generating a Read-Only Token in Turso:
12	1. Open **[https://app.turso.tech](https://app.turso.tech)**.
13	2. Navigate to your database (`heraclitus-rien-bluerose`).
14	3. Click the **Tokens** tab -> **"Create Token"**.
15	4. Set Name: `esp32-readonly`.
16	5. Toggle **"Read-only"**: **ON** (`true`).
17	6. Set Expiration: **Never** (or preferred timeframe).
18	7. Copy the generated read-only token into your ESP32 sketch.
19	
20	*(Any attempt by firmware using this token to execute `INSERT`, `UPDATE`, or `DELETE` is automatically rejected by the Turso kernel with HTTP 403).*
21	
22	---
23	
24	## 2. Minimal Metadata Rendering Specification
25	
26	For microcontrollers with limited display canvas (E-Paper, TFT, OLED) and audio engines, the lesser the metadata, the better. We strip away internal UUIDs, backlinks, and shadow tags, distilling each quote to **5 essential display dimensions**:
27	
28	| # | Dimension | Field Name | Description | Fallback Rule |
29	|---|---|---|---|---|
30	| **1** | **Content** | `content` | The core wisdom quote / poem text | Required |
31	| **2** | **Context** | `context` | Situational backdrop & reflection | Empty string if absent |
32	| **3** | **Origin / Creator** | `container_name` | The author, persona, or franchise (e.g. *William Blake*, *Faust*) | Joined from Table 2 |
33	| **4** | **Specific Endpoint** | `specific_name` | The work, chapter, or song (e.g. *Infant Joy*, *Koi no Koe*) | Joined from Table 3 |
34	| **5** | **Effective Date** | `effective_date` | The temporal coordinate (e.g. `2026-09-30`, `1789`) | **Display-time fallback**: If quote date is empty, automatically uses `specific.date` without mutating database |
35	| **+** | **Thematic Anchor** | `theme_names` | Plain text comma-separated conceptual labels (e.g. *Heartbroken*, *Order & Entropy*) | Resolved from Table 4 |
36	| **+** | **Evaluation & Scoring** | `scores`, `average_score` | List of scoring ratings (e.g. `[5,6,4,7,5]`) and arithmetic average (e.g. `5.4`) | `[]` and `null` if unrated |
37	
38	---
39	
40	## 3. The Unified Edge SQL Query (One-Trip Resolution)
41	
42	Rather than forcing the ESP32 to make multiple network roundtrips to join tables, we let Turso's SQLite engine perform the join and fallback at the edge. The ESP32 sends a single query and receives the complete bundle:
43	
44	### Query: Fetch Random Quote for Rendering
45	```sql
46	SELECT 
47	    q.idx,
48	    q.main_content AS content,
49	    COALESCE(q.context, '') AS context,
50	    COALESCE(NULLIF(q.date, ''), s.date, '') AS effective_date,
51	    COALESCE(s.name, '') AS specific_name,
52	    COALESCE(c.name, '') AS container_name,
53	    COALESCE(s.category, '') AS category,
54	    COALESCE((
55	        SELECT GROUP_CONCAT(t.name, ', ')
56	        FROM themes t
57	        WHERE t.id IN (SELECT value FROM json_each(q.theme_ids))
58	    ), '') AS theme_names
59	FROM quotes q
60	LEFT JOIN specifics s ON q.specific_id = s.id
61	LEFT JOIN containers c ON s.container_id = c.id
62	ORDER BY RANDOM() LIMIT 1;
63	```
64	
65	### Query: Fetch Latest Quote for Rendering
66	```sql
67	SELECT 
68	    q.idx,
69	    q.main_content AS content,
70	    COALESCE(q.context, '') AS context,
71	    COALESCE(NULLIF(q.date, ''), s.date, '') AS effective_date,
72	    COALESCE(s.name, '') AS specific_name,
73	    COALESCE(c.name, '') AS container_name,
74	    COALESCE(s.category, '') AS category,
75	    COALESCE((
76	        SELECT GROUP_CONCAT(t.name, ', ')
77	        FROM themes t
78	        WHERE t.id IN (SELECT value FROM json_each(q.theme_ids))
79	    ), '') AS theme_names
80	FROM quotes q
81	LEFT JOIN specifics s ON q.specific_id = s.id
82	LEFT JOIN containers c ON s.container_id = c.id
83	ORDER BY q.idx DESC LIMIT 1;
84	```
85	
86	---
87	
88	## 4. Complete Read-Only Arduino C++ Sketch
89	
90	Install via Arduino IDE Library Manager:
91	- **`ArduinoJson`** (v6 or v7 by Benoit Blanchon)
92	
93	```cpp
94	#include <WiFi.h>
95	#include <WiFiClientSecure.h>
96	#include <HTTPClient.h>
97	#include <ArduinoJson.h>
98	
99	// ==============================================================================
100	// 1. CONFIGURATION
101	// ==============================================================================
102	const char* ssid          = "YOUR_WIFI_SSID";
103	const char* password      = "YOUR_WIFI_PASSWORD";
104	
105	// Turso Database HTTP Endpoint (Sydney AWS edge)
106	const char* turso_url     = "https://heraclitus-rien-bluerose.aws-ap-southeast-2.turso.io/v2/pipeline";
107	
108	// Paste your dedicated Read-Only token here
109	const char* turso_ro_token = "YOUR_READ_ONLY_TOKEN";
110	
111	// ==============================================================================
112	// 2. DATA RECEPTACLE (MINIMAL 5-POINT METADATA STRUCT)
113	// ==============================================================================
114	struct QuoteRenderPayload {
115	  long idx;
116	  String content;
117	  String context;
118	  String effectiveDate;
119	  String specificName;
120	  String containerName;
121	  String category;
122	  String themeNames;
123	};
124	
125	// ==============================================================================
126	// 3. SECURE READ-ONLY TURSO FETCHER
127	// ==============================================================================
128	bool fetchQuoteFromTurso(QuoteRenderPayload &out, bool randomQuote = true) {
129	  if (WiFi.status() != WL_CONNECTED) {
130	    Serial.println("[WIFI] Reconnecting to Wi-Fi...");
131	    WiFi.begin(ssid, password);
132	    int retries = 0;
133	    while (WiFi.status() != WL_CONNECTED && retries < 15) {
134	      delay(500);
135	      retries++;
136	    }
137	    if (WiFi.status() != WL_CONNECTED) return false;
138	  }
139	
140	  WiFiClientSecure client;
141	  client.setInsecure(); // Saves RAM by bypassing full X.509 cert chain validation
142	
143	  HTTPClient http;
144	  http.begin(client, turso_url);
145	  http.addHeader("Content-Type", "application/json");
146	  http.addHeader("Authorization", String("Bearer ") + turso_ro_token);
147	
148	  // The minimal metadata query with date fallback, joined names, and category
149	  String sql = "SELECT "
150	               "q.idx, "
151	               "q.main_content AS content, "
152	               "COALESCE(q.context, '') AS context, "
153	               "COALESCE(NULLIF(q.date, ''), s.date, '') AS effective_date, "
154	               "COALESCE(s.name, '') AS specific_name, "
155	               "COALESCE(c.name, '') AS container_name, "
156	               "COALESCE(s.category, '') AS category, "
157	               "COALESCE((SELECT GROUP_CONCAT(t.name, ', ') FROM themes t WHERE t.id IN (SELECT value FROM json_each(q.theme_ids))), '') AS theme_names "
158	               "FROM quotes q "
159	               "LEFT JOIN specifics s ON q.specific_id = s.id "
160	               "LEFT JOIN containers c ON s.container_id = c.id ";
161	
162	  sql += randomQuote ? "ORDER BY RANDOM() LIMIT 1;" : "ORDER BY q.idx DESC LIMIT 1;";
163	
164	  // Escape quotation marks for JSON payload
165	  sql.replace("\"", "\\\"");
166	
167	  String payload = "{\"requests\":[{\"type\":\"execute\",\"stmt\":{\"sql\":\"" + sql + "\"}},{\"type\":\"close\"}]}";
168	
169	  Serial.println("[TURSO] Executing Read-Only SQL query...");
170	  int httpCode = http.POST(payload);
171	
172	  if (httpCode == 200) {
173	    String response = http.getString();
174	    
175	    // Parse response with ArduinoJson (Lightweight ~2 KB buffer)
176	    DynamicJsonDocument doc(4096);
177	    DeserializationError error = deserializeJson(doc, response);
178	
179	    if (!error) {
180	      JsonArray rows = doc["results"][0]["response"]["result"]["rows"];
181	      if (rows.size() > 0) {
182	        out.idx           = rows[0][0]["value"].as<long>();
183	        out.content       = rows[0][1]["value"].as<String>();
184	        out.context       = rows[0][2]["value"].as<String>();
185	        out.effectiveDate = rows[0][3]["value"].as<String>();
186	        out.specificName  = rows[0][4]["value"].as<String>();
187	        out.containerName = rows[0][5]["value"].as<String>();
188	        out.category      = rows[0][6]["value"].as<String>();
189	        out.themeNames    = rows[0][7]["value"].as<String>();
190	
191	        http.end();
192	        return true;
193	      } else {
194	        Serial.println("[TURSO] Database returned 0 rows.");
195	      }
196	    } else {
197	      Serial.print("[JSON] Deserialization error: ");
198	      Serial.println(error.c_str());
199	    }
200	  } else {
201	    Serial.printf("[HTTP] Error %d: %s\n", httpCode, http.getString().c_str());
202	  }
203	
204	  http.end();
205	  return false;
206	}
207	
208	// ==============================================================================
209	// 4. DISPLAY / RENDER FUNCTION (VISION SPECIFICATION)
210	// ==============================================================================
211	// ANSI 256-Color & RGB Codes for Microcontroller Displays & Serial Terminal:
212	#define ANSI_RESET        "\033[0m"
213	#define ANSI_WHITE        "\033[1;37m"
214	#define ANSI_GHOST_GRAY   "\033[38;5;242m"  // Muted ghost gray for header coordinates
215	#define ANSI_ACCENT_BLUE  "\033[38;5;75m"   // Sapphire Blue (#38bdf8)
216	#define ANSI_ACCENT_GOLD  "\033[38;5;214m"  // Imperial Gold (#f59e0b)
217	
218	// Vast Independent Tag Color Pool (16+ Distinct Microcontroller Colors):
219	const char* TAG_COLOR_POOL[] = {
220	  "\033[38;5;75m",  // Sapphire Blue
221	  "\033[38;5;214m", // Amber Gold
222	  "\033[38;5;44m",  // Sky Cyan
223	  "\033[38;5;42m",  // Emerald Green
224	  "\033[38;5;204m", // Crimson Rose
225	  "\033[38;5;177m", // Royal Violet
226	  "\033[38;5;208m", // Tangerine
227	  "\033[38;5;141m", // Lavender
228	  "\033[38;5;80m",  // Aquamarine
229	  "\033[38;5;219m", // Orchid
230	  "\033[38;5;119m", // Spring Mint
231	  "\033[38;5;220m", // Bright Topaz
232	  "\033[38;5;168m", // Magenta
233	  "\033[38;5;69m",  // Cobalt
234	  "\033[38;5;172m", // Ochre
235	  "\033[38;5;51m"   // Electric Aqua
236	};
237	const int TAG_COLOR_COUNT = 16;
238	
239	void renderQuote(const QuoteRenderPayload &q) {
240	  // 1. Randomly pick ONE shared color for quotation marks & container (Pool of 2: Gold or Blue)
241	  bool pickGold = ((q.idx % 2) == 0); // Deterministic per quote or use random(0, 2)
242	  const char* sharedAccent = pickGold ? ANSI_ACCENT_GOLD : ANSI_ACCENT_BLUE;
243	
244	  Serial.println("\n┌──────────────────────────────────────────────────────────────────────────┐");
245	  
246	  // 2. Header: #IDX ~ Specific on left, Date: <date> on right (Ghost gray & smaller)
247	  String headerLeft = "#" + String(q.idx) + " ~ " + q.specificName;
248	  String headerRight = "Date: " + q.effectiveDate;
249	  Serial.printf("│ " ANSI_GHOST_GRAY "%-44s" ANSI_RESET "  " ANSI_GHOST_GRAY "%24s" ANSI_RESET " │\n", 
250	                headerLeft.c_str(), headerRight.c_str());
251	  Serial.println("├──────────────────────────────────────────────────────────────────────────┤");
252	  
253	  // 3. Content: Italic-feel wrapped in distinct quotation marks sharing container's accent color
254	  bool isWriting = q.category.equalsIgnoreCase("writing") || q.category.equalsIgnoreCase("bài viết");
255	  Serial.printf("│ %s“" ANSI_RESET ANSI_WHITE "%s" ANSI_RESET "%s”" ANSI_RESET "\n", 
256	                sharedAccent, q.content.c_str(), sharedAccent);
257	  
258	  if (q.context.length() > 0) {
259	    Serial.printf("│\n│ " ANSI_GHOST_GRAY "[%s]" ANSI_RESET "\n", q.context.c_str());
260	  }
261	
262	  Serial.println("├──────────────────────────────────────────────────────────────────────────┤");
263	  
264	  // 4. Footer: Each tag has a distinct random color block (left) · Container shares mark's color (right)
265	  String tagsFormatted = "";
266	  if (q.themeNames.length() > 0) {
267	    int start = 0;
268	    int tagIndex = 0;
269	    while (start < q.themeNames.length()) {
270	      int comma = q.themeNames.indexOf(',', start);
271	      if (comma == -1) comma = q.themeNames.length();
272	      String tag = q.themeNames.substring(start, comma);
273	      tag.trim();
274	      if (tag.length() > 0) {
275	        const char* tagColor = TAG_COLOR_POOL[(q.idx + tagIndex) % TAG_COLOR_COUNT];
276	        if (tagsFormatted.length() > 0) tagsFormatted += " ";
277	        tagsFormatted += String(tagColor) + "[" + "#" + tag + "]" + ANSI_RESET;
278	        tagIndex++;
279	      }
280	      start = comma + 1;
281	    }
282	  }
283	
284	  Serial.printf("│ %-48s  %s%24s" ANSI_RESET " │\n", 
285	                tagsFormatted.c_str(), sharedAccent, q.containerName.c_str());
286	  Serial.println("└──────────────────────────────────────────────────────────────────────────┘\n");
287	
288	  // On physical TFT/E-Paper displays (e.g. GxEPD2 or LovyanGFX):
289	  // - Render header text with smaller font (e.g. 9pt) in ghost gray
290	  // - Render quotes and container with shared accent color (Gold or Blue)
291	  // - Render each tag capsule with its designated palette color!
292	}
293	
294	// ==============================================================================
295	// 5. MAIN ARDUINO ENTRYPOINTS
296	// ==============================================================================
