  if (q.context.length() > 0) {
    Serial.printf("│\n│ " ANSI_GHOST_GRAY "[%s]" ANSI_RESET "\n", q.context.c_str());
  }

  Serial.println("├──────────────────────────────────────────────────────────────────────────┤");

  // 4. Footer: Each tag has a distinct random color block (left) · Container shares mark's color (right)
  String tagsFormatted = "";
