26	#include "WiFiMulti.h"
27	#if SOC_WIFI_SUPPORTED || CONFIG_ESP_HOSTED_ENABLED
28	#include <limits.h>
29	#include <string.h>
30	#include <esp32-hal.h>
31	
32	WiFiMulti::WiFiMulti() {
33	  ipv6_support = false;
34	}
35	
36	void WiFiMulti::APlistClean(void) {
37	  for (auto entry : APlist) {
38	    if (entry.ssid) {
39	      free(entry.ssid);
40	    }
41	    if (entry.passphrase) {
42	      free(entry.passphrase);
43	    }
44	#if CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT
45	    if (entry.username) {
46	      free(entry.username);
47	    }
48	    if (entry.identity) {
49	      free(entry.identity);
50	    }
51	#endif /* CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT */
52	  }
53	  APlist.clear();
54	}
55	
56	WiFiMulti::~WiFiMulti() {
57	  APlistClean();
58	}
59	
60	#if CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT
61	bool WiFiMulti::addAP(const char *ssid, const char *passphrase, const char *username, const char *identity) {
62	#else
63	bool WiFiMulti::addAP(const char *ssid, const char *passphrase) {
64	#endif /* CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT */
65	  WifiAPlist_t newAP;
66	
67	  if (!ssid || *ssid == '\0' || strlen(ssid) > 31) {
68	    // fail SSID too long or missing!
69	    log_e("[WIFI][APlistAdd] no ssid or ssid too long");
70	    return false;
71	  }
72	
73	  if (passphrase && strlen(passphrase) > 63) {
74	    // fail passphrase too long!
75	    log_e("[WIFI][APlistAdd] passphrase too long");
76	    return false;
77	  }
78	
79	#if CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT
80	  if (username && strlen(username) > 63) {
81	    // fail username too long!
82	    log_e("[WIFI][APlistAdd] username too long");
83	    return false;
84	  }
85	
86	  if (identity && strlen(identity) > 63) {
87	    // fail identity too long!
88	    log_e("[WIFI][APlistAdd] identity too long");
89	    return false;
90	  }
91	#endif /* CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT */
92	
93	  newAP.ssid = strdup(ssid);
94	
95	  if (!newAP.ssid) {
96	    log_e("[WIFI][APlistAdd] fail newAP.ssid == 0");
97	    return false;
98	  }
99	
100	  if (passphrase && *passphrase != '\0') {
101	    newAP.passphrase = strdup(passphrase);
102	    if (!newAP.passphrase) {
103	      log_e("[WIFI][APlistAdd] fail newAP.passphrase == 0");
104	      free(newAP.ssid);
105	      return false;
106	    }
107	  } else {
108	    newAP.passphrase = NULL;
109	  }
110	
111	#if CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT
112	  if (username && *username != '\0') {
113	    newAP.username = strdup(username);
114	    if (!newAP.username) {
115	      log_e("[WIFI][APlistAdd] fail newAP.username == 0");
116	      free(newAP.ssid);
117	      if (newAP.passphrase) {
118	        free(newAP.passphrase);
119	      }
120	      return false;
121	    }
122	  } else {
123	    newAP.username = NULL;
124	  }
125	
126	  if (identity) {  // Allow empty identity as not all WPA2-Enterprise networks require it
127	    newAP.identity = strdup(identity);
128	    if (!newAP.identity) {
129	      log_e("[WIFI][APlistAdd] fail newAP.identity == 0");
130	      free(newAP.ssid);
131	      if (newAP.passphrase) {
