        bestBSSID[4], bestBSSID[5], bestNetwork.ssid, bestChannel, bestNetworkDb
      );

#if CONFIG_LWIP_IPV6
      if (ipv6_support == true) {
        WiFi.enableIPv6();
      }
#endif
      WiFi.disconnect();
      delay(10);
