#else
      WiFi.begin(bestNetwork.ssid, (bestNetworkSec == WIFI_AUTH_OPEN) ? NULL : bestNetwork.passphrase, bestChannel, bestBSSID);
#endif /* CONFIG_ESP_WIFI_ENTERPRISE_SUPPORT */
